@js:
var baseUrlStr = String(baseUrl);
var html = java.ajax(baseUrlStr);
var all = [];
var doc = org.jsoup.Jsoup.parse(html);
var scripts = doc.select("div#chaptercontent script");

for (var i = 0; i < scripts.size(); i++) {
  var s = scripts.get(i).html();
  var m = s.match(/qsbs\.bb\('([^']+)'\)/);
  var mdata = m ? m[1] : "";
  if (mdata) {
    var dec = java.base64Decode(mdata);
    var t = org.jsoup.Jsoup.parse(dec).text().trim();
    if (t) all.push(t);
  }
}
result = all.join("\n");

ruleToc.chapterList:
@js:
var baseUrlStr = String(baseUrl);
var html = java.ajax(baseUrlStr);
var doc = org.jsoup.Jsoup.parse(html);
var allElements = new org.jsoup.select.Elements();
var seen = {}; // 记录抓过的章节链接，用于查重和防死循环

// 1. 处理第一页（详情页）
var item = doc.select("div.book_list dl dd");
if (item.size() == 0) item = doc.select("div.book_last dl dd");
if (item.size() == 0) item = doc.select("#list dd");

// 排除第一页前 12 条最新章（如果大于12条）
var start = item.size() > 12? 12: 0;
for (var i = start; i < item.size(); i++) {
    var a = item.get(i).selectFirst("a");
    if (a) {
        seen[a.attr("href")] = true;
        allElements.add(item.get(i));
    }
}

// 2. 暴力循环请求所有分页
var match = baseUrlStr.match(/\/book\/(\d+)/);
if (match) {
    var bookId = match[1];
    var domain = baseUrlStr.match(/^https?:\/\/[^\/]+/)[0];

    // 🎯 上限设为 100 页，足以应对 10000 章以下的小说
    for (var p = 1; p <= 100; p++) {
        var pageUrl = domain + "/chapters/" + bookId + "/" + p + ".html";
        java.log(pageUrl);
        var pageHtml = java.ajax(pageUrl);

        // 如果页面不存在或者抓取失败，停止
        if (!pageHtml || pageHtml.length < 1000) break; 

        var pageDoc = org.jsoup.Jsoup.parse(pageHtml);
        var pageItems = pageDoc.select("div.book_list dl dd");
        if (pageItems.size() == 0) pageItems = pageDoc.select("div.book_last dl dd");
        if (pageItems.size() == 0) pageItems = pageDoc.select("#list dd");

        if (pageItems.size() == 0) break;

        // 🎯 动态拦截：检查这一页的第一章是不是已经抓过了
        var firstA = pageItems.first().selectFirst("a");
        if (firstA && seen[firstA.attr("href")]) {
            java.log("第 " + p + " 页出现了重叠的旧章节，已自动拦截停止抓取！");
            break; // 遇到重复页直接跑路，绝不拼接垃圾数据
        }

        // 没有重复，原样把这一页的章节加进去
        for (var k = 0; k < pageItems.size(); k++) {
            var aEl = pageItems.get(k).selectFirst("a");
            if (aEl) {
                var href = aEl.attr("href");
                if (!seen[href]) {
                    seen[href] = true;
                    allElements.add(pageItems.get(k));
                }
            }
        }
    }
}

java.log("全自动抓取完成，总计条数=" + allElements.size());
allElements;
